vector<bool> sieve(int n) {
    vector<bool> prime(n + 1, true);
    prime[0] = prime[1] = false;
    for (int i = 2; (long long)i * i <= n; i++)
        if (prime[i])
            for (int j = i * i; j <= n; j += i)   // cross out multiples of i
                prime[j] = false;
    return prime;   // prime[k] tells if k is prime
}

