def sieve(n):
    prime = [True] * (n + 1)
    prime[0] = prime[1] = False
    i = 2
    while i * i <= n:
        if prime[i]:
            for j in range(i * i, n + 1, i):      # cross out multiples of i
                prime[j] = False
        i += 1
    return prime   # prime[k] tells if k is prime

